args.command:
adb shell uiautomator dump /sdcard/ui.xml && adb shell cat /sdcard/ui.xml | python3 -c "
import sys, xml.etree.ElementTree as ET
tree = ET.parse(sys.stdin)
for node in tree.iter('node'):
    text, desc = node.get('text',''), node.get('content-desc','')
    if text or desc:
        bounds = node.get('bounds')
        if text in ['Start', 'Stop', 'Low', 'Medium', 'High'] or 'CPU' in text or 'GPU' in text:
            print(f'text={text!r} desc={desc!r} bounds={bounds}')
"
